#include "battle/Snapshot.h"
#include <bit>
namespace battle {
Snapshot Capture(const World&w){return {1,w};}
Result<World> Restore(const Snapshot&s){if(s.schema_version!=1)return {Status::InvalidInput,{},{{"snapshot",0,"unsupported snapshot version"}}};auto v=ValidateScenario(s.state.scenario);if(!v)return {v.status,{},v.diagnostics};return {Status::Ok,s.state,{}};}
namespace {
struct Hash{uint64_t h{14695981039346656037ull};void n(uint64_t v){for(int i=0;i<8;++i){h^=v&255;h*=1099511628211ull;v>>=8;}};void f(float v){n(std::bit_cast<uint32_t>(v));}void text(const std::string&s){n(s.size());for(unsigned char c:s)n(c);}void vec(Vec3 p){f(p.x);f(p.y);f(p.z);}void pose(Pose p){vec(p.position);f(p.yaw);}void formation(FormationSpec s){n(s.columns);f(s.spacing_m);f(s.body_radius_m);}void weapon(const WeaponSpec&s){f(s.damage);f(s.range);n(s.cooldown_ticks);n(s.windup_ticks);f(s.projectile_speed_mps);f(s.base_accuracy);}void order(const Order&o){n(o.id.value);n(o.issuer.value);n(o.recipient.value);n(uint8_t(o.type));n(uint64_t(o.priority));vec(o.point);n(o.target_unit.value);n(o.target_regiment.value);n(o.created_tick);n(o.delivery_tick);n(o.expiry_tick);n(uint8_t(o.status));}void cmd(const CommandEnvelope&e){n(e.tick);n(e.sequence);const auto&c=e.command;n(uint8_t(c.kind));order(c.order);n(c.regiment.value);formation(c.formation);n(c.unit.value);n(c.target.value);vec(c.velocity);pose(c.pose);n(c.sample_tick);}void unit(const UnitSpec&u){n(u.id.value);n(u.regiment.value);text(u.name);pose(u.pose);f(u.health);f(u.speed);f(u.armour);f(u.archer_skill);n(u.archer);n(uint64_t(u.legacy_id));weapon(u.weapon);n(u.equipment.size());for(auto i:u.equipment)n(i);}};
}
uint64_t StateHash(const World&w){Hash h;h.n(w.tick);h.n(w.seed);h.n(w.next_event_id);h.n(w.next_order_id);h.n(w.controlled.value);
    h.n(w.units.size());for(const auto&u:w.units){h.unit(u);h.n(u.alive);h.n(uint8_t(u.control));h.pose(u.slot);h.n(u.slot_index);h.n(u.ready_tick);h.vec(u.desired_velocity);h.n(u.attack_target.value);}
    h.n(w.regiments.size());for(const auto&r:w.regiments){h.n(r.id.value);h.n(uint64_t(r.team));h.text(r.name);h.pose(r.pose);h.formation(r.formation);h.f(r.speed);h.f(r.turn_rate);h.vec(r.rally_point);h.n(r.units.size());for(auto id:r.units)h.n(id.value);h.n(r.slots.size());for(auto p:r.slots)h.pose(p);h.n(r.route.size());for(auto p:r.route)h.pose(p);h.n(r.waypoint);h.n(r.order.has_value());if(r.order)h.order(*r.order);h.n(r.initial_count);h.n(r.panic);h.n(r.calm_counter);h.n(r.last_damage_tick);h.n(r.decision_tick);h.n(r.decision_until);h.n(uint8_t(r.ai_action));h.n(r.ai_target.value);}
    for(const auto&o:w.officers){h.n(o.id.value);h.n(o.unit.value);h.n(o.role);h.f(o.charisma);h.f(o.tactic_mind);h.f(o.lead_skill);h.f(o.lead_dist);h.n(uint64_t(o.legacy_id));}
    h.n(w.attacks.size());for(auto&a:w.attacks){h.n(a.id.value);h.n(a.source.value);h.n(a.target.value);h.n(a.due_tick);h.f(a.damage);h.n(a.hit);}h.n(w.pending_orders.size());for(auto&o:w.pending_orders)h.order(o);h.n(w.commands.size());for(auto&e:w.commands)h.cmd(e);h.n(w.accepted_sequences.size());for(auto s:w.accepted_sequences)h.n(s);
    const auto&rules=w.scenario.rules;h.f(rules.panic_fraction);h.n(rules.calm_ticks);h.f(rules.rally_tolerance_m);h.f(rules.rally_safe_radius_m);for(auto&o:w.scenario.obstacles){h.f(o.min_x);h.f(o.min_y);h.f(o.max_x);h.f(o.max_y);}return h.h;
}
}
